  Notation WT := [(SP - 2208, SP); (HW, HW + 256); (RK, RK + 52); (NSP, NSP + 4); (TLP, TLP + 4)].

  Lemma prs_out_stkA : forall a, PRS a -> ~ (SP - 2208 <= a < SP).
  Proof.
    intros a (CA & _) Hs. pose proof ATOP_range as ATR. unfold AHUF_RSTATS_STACK in LO.
    assert (AIT : AIMG_HI < ATOP) by (unfold AIMG_HI, ATOP_MIN in *; lia).
    destruct CA as [C1 | [(iv & IN & I1) | [(b & IN & B1) | (a' & C4 & E)]]].
    - lia.
    - pose proof (AI_aci_img AI iv IN). lia.
    - pose proof (ablk_lin _ _ (LBH b IN)). lia.
    - subst a. assert (A47 : a' < 2^47).
      { destruct C4 as [C|[(iv & IN & I1)|(cls & A & n & IN & I1)]];
          [lia | pose proof (AI_aci_img AI iv IN); lia | pose proof (ablk_lin _ _ (LBH _ IN)); cbn in *; lia]. }
      unfold shad in Hs. rewrite Z.shiftr_div_pow2 in Hs by lia.
      assert (a' / 2^3 < 2^44) by (apply Z.div_lt_upper_bound; lia).
      unfold ASHOFF, ATOP_MIN in *. lia.
  Qed.

  (* [comment removed for export] *)
  Lemma rsA_join : forall mj ws junk iS jr' nsv' tlv' (x1 x5 x6 x7 x10 x11 x15 x16 x17 x19 x21 x22 x28 x29 x30 x31 : word),
    read_stats src = RF_huf_rs_pure.rs_tail ws (zlen ws) iS ->
    zlen ws <= 255 -> Forall (fun c => 0 <= c < 256) ws -> zlen junk = 256 - zlen ws -> 0 <= iS <= 128 ->
    u8arr bsegs mj RK jr' -> zlen jr' = 52 -> u8arr bsegs mj HW (map (Z_to_bv 8) ws ++ junk) ->
    rw_cells bsegs mj NSP [C4 nsv'] -> rw_cells bsegs mj TLP [C4 tlv'] ->
    rw_cells bsegs mj SP FRM -> stk bsegs mj lo SP -> mem_inv bsegs mj ->
    magree bsegs PRS m0 mj -> AHEAP AI L RNG st LB mj ->
    evtF bsegs RNG POST
      (MS (mkR x1 (Z_to_bv 64 SP) gp tp x5 x6 x7 (Z_to_bv 64 RK) (Z_to_bv 64 (zlen ws)) x10 x11 (Z_to_bv 64 HW) (Z_to_bv 64 NSP)
               (Z_to_bv 64 TLP) x15 x16 x17 (Z_to_bv 64 iS) x19 (Z_to_bv 64 2147450880) x21 x22
               s7 s8 s9 s10 s11 x28 x29 x30 x31)
          FR (Z_to_bv 64 0x974f8) fc None mj (seg_rom bsegs)).
Proof.
intros mj ws junk iS jr' nsv' tlv' x1 x5 x6 x7 x10 x11 x15 x16 x17 x19 x21 x22 x28 x29 x30 x31
  RS HWS HWB HJK HIS RKj HJR HWj NSj TLj FRC STj MIj MG AHj.
pose proof rsA_regions as (AHW & ARK & AWK & ANS & ATL & _).
pose proof (disj_hf HW 256 NSP 4 HHW FNS ltac:(lia) ltac:(lia)) as DHN.
pose proof (disj_hf HW 256 TLP 4 HHW FTL ltac:(lia) ltac:(lia)) as DHT.
pose proof (disj_hf RK 52 NSP 4 HRK FNS ltac:(lia) ltac:(lia)) as DRN.
pose proof (disj_hf RK 52 TLP 4 HRK FTL ltac:(lia) ltac:(lia)) as DRT.
pose proof (fcellA_mg _ _ _ _ _ _ MG prs_shad_fake FNS) as (_ & UNSj).
pose proof (fcellA_mg _ _ _ _ _ _ MG prs_shad_fake FTL) as (_ & UTLj).
assert (ZHWj : zshadow mj HW 256) by (eapply zshadow_of_hblk8; [exact AHj|exact HHW|lia]).
assert (ZRKj : zshadow mj RK 52) by (eapply zshadow_of_hblk8; [exact AHj|exact HRK|lia]).
assert (RGHW : rng RNG HW 256 /\ rng RNG (shad HW) (nshad (256 + HW mod 8))) by (eapply rng_of_hblk8; [exact AHj|exact HHW|lia]).
assert (RGRK : rng RNG RK 52 /\ rng RNG (shad RK) (nshad (52 + RK mod 8))) by (eapply rng_of_hblk8; [exact AHj|exact HRK|lia]).
destruct RGHW as (RHW & RHWs). destruct RGRK as (RRK & RRKs).
pose proof (AI_rtcells _ _ _ _ _ _ AHj) as RTCj.
pose proof HRK as (pR & AR & NR & INR & NR8 & XR & XR2).
pose proof (AI_block _ _ _ _ _ _ _ _ _ AHj INR) as (_ & BRG & _ & _ & _ & _ & _ & BLO & BHI & R1 & R2 & R3 & R4 & R5 & R6).
pose proof (ablk_lin _ _ ARK) as (RKa & RKb & RKc & RKd).
pose proof (ablk_lin _ _ AHW) as (HWa & HWb & HWc & HWd).
pose proof (ablk_lin _ _ ANS) as (NSa & NSb & NSc & NSd).
pose proof (ablk_lin _ _ ATL) as (TLa & TLb & TLc & TLd).
assert (A64 : 64 <= RK) by (unfold AIMG_HI in RKa; lia).
pose proof (block_hullR RNG mj RK 52 BLO BHI ltac:(lia) R1 R2 ltac:(lia) ltac:(lia) A64 R5 R6) as (HRR & HWR & H1 & H2 & H3 & H4 & H5 & H6).
pose proof ATOP_range as ATR.
destruct (AI_layout _ _ _ _ _ _ AHj) as (_ & _ & ALT & _).
unfold AHUF_RSTATS_STACK in LO.
eapply (AF_huf_rs_tail.tlA SP gp tp FR fc s7 s8 s9 s10 s11 x29 x30 x31 mj RNG HW RK NSP TLP iS lo (hull_loR RK) (hull_hiR RK 52) ws jr' junk nsv' tlv' POST);
  [ lia | exact HWB | exact HIS | exact HJK | exact HJR | exact AHW | exact ARK | exact RK4 | exact ANS | exact ATL
  | exact NS4 | exact TL4 | exact DHR | exact DHN | exact DHT | exact DRN | exact DRT | exact DNT
  | exact RKj | exact HWj | exact NSj | exact TLj | exact MIj | exact RTCj | exact STj | exact BOT | lia | lia
  | exact ZHWj | exact ZRKj | exact UNSj | exact UTLj
  | repeat split; try assumption; unfold KEND, ATOP_MAX in *; lia
