eapply (rsA_exit m2 _ a0v); [ | exact ST2 | exact MI2 | | | exact RS | exact RR ].
- eapply rw_cells_transport; [exact FRC|exact MU2|exact WM2|]. cbn. lia.
- eapply magree_trans; [exact MG|]. eapply AProg_kit.munch_magreeA; [exact MU2|exact WM2|].
  intros a PA. pose proof (prs_out_stkA a PA) as PO. destruct PA as (_ & PH1 & PH2 & PH3 & PH4 & _). cbn [outside].
  exact (conj PO (conj PH1 (conj PH2 (conj PH3 (conj PH4 I))))).
- eapply AI_frame; [exact AHj|exact MU2|exact WM2|].
  pose proof HHW as (pH & AH0 & NH0 & INH & _ & XH & XH2).
  pose proof FNS as ((clN & FAN & FNN & INN & XN & XN2 & _) & _).
  pose proof FTL as ((clT & FAT & FNT & INT & XT & XT2 & _) & _).
  repeat apply Forall_cons; [ | | | | | apply Forall_nil ]; cbn [fst snd].
  + left. left. lia.
  + right. left. exists (HB pH AH0 NH0). cbn. split; [exact INH|lia].
  + right. left. exists (HB pR AR NR). cbn. split; [exact INR|lia].
  + right. left. eexists. split; [exact INN|cbn; lia].
  + right. left. eexists. split; [exact INT|cbn; lia].
Qed.

