      (MS (mkR ra (Z_to_bv 64 SPV) gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 HW) (Z_to_bv 64 256) (Z_to_bv 64 RK) (Z_to_bv 64 NSP)
               (Z_to_bv 64 TLP) (Z_to_bv 64 S) (Z_to_bv 64 (zlen src)) (Z_to_bv 64 W) s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
          FR (Z_to_bv 64 AHUF_RSTATS) fc None m0 (seg_rom bsegs)).
Proof.
intros t0 t1 t2 t3 t4 t5 t6.
pose proof rsA_regions as (AHW & ARK & AWK & ANS & ATL & AS).
pose proof LO as LO'. unfold AHUF_RSTATS_STACK in LO'.
remember m0 as mm eqn:EM in |- *.
assert (STm : stk bsegs mm lo SPV) by (subst mm; exact ST).
assert (MIm : mem_inv bsegs mm) by (subst mm; exact MI).
assert (RTC : artcells mm) by (subst mm; exact (AI_rtcells AI _ _ _ _ _ AH)). unfold artcells in RTC.
destruct RTC as (RC0 & RGOT & RIC & REAL & RSHB & RSUA & RINI & RLAY & _).
destruct (stk_carve bsegs mm lo SPV 64 STm ltac:(lia)) as [STL [junk FR0]]. clear STm.
change (Z.of_nat 64) with 64 in STL, FR0. replace (SPV - 64) with (SPV + -64) in STL, FR0 by lia.
pose proof (rw_cells_split_CB bsegs _ (SPV + -64) [] 64 junk [] [8; 8; 8; 8; 8; 8; 8; 8]%nat FR0 eq_refl) as FRA2.
cbn [app mk_CB_cells] in FRA2. clear FR0.
pose proof (munch_refl [(SPV + -64, SPV)] mm) as MU. pose proof (wmono_refl bsegs mm) as WM.
hide_djR.
do 13 zstep.
subst mm.
assert (OUTS : forall a, aclient_addr CI LB SPV a -> ~ (SPV + -64 <= a < SPV)).
{ intros a CA Hs. pose proof ATOP_range as ATR.
  assert (AIT : AIMG_HI < ATOP) by (unfold AIMG_HI, ATOP_MIN in *; lia).
  destruct CA as [C1 | [(iv & IN & I1) | [(b & IN & B1) | (a' & C4 & E)]]].
  - lia.
  - pose proof (AI_aci_img AI iv IN). lia.
  - pose proof (ablk_lin _ _ (LBH b IN)). lia.
  - subst a. assert (A47 : a' < 2^47).
    { destruct C4 as [C|[(iv & IN & I1)|(cls & A & n & IN & I1)]];
        [lia | pose proof (AI_aci_img AI iv IN); lia | pose proof (ablk_lin _ _ (LBH _ IN)); cbn in *; lia]. }
    unfold shad in Hs. rewrite Z.shiftr_div_pow2 in Hs by lia.
    assert (a' / 2^3 < 2^44) by (apply Z.div_lt_upper_bound; lia).
    unfold ASHOFF, ATOP_MIN in *. lia. }
assert (MG1 : magree bsegs (aclient_addr CI LB SPV) m0 m1).
{ eapply AProg_kit.munch_magreeA; [exact MU|exact WM|]. intros a CA. cbn [outside]. exact (conj (OUTS a CA) I). }
assert (AH1 : AHEAP AI L RNG st LB m1).
{ destruct (AI_layout _ _ _ _ _ _ AH) as (_ & _ & ALT & _).
  eapply AI_frame; [exact AH|exact MU|exact WM|]. apply Forall_cons; [|apply Forall_nil]. cbn [fst snd]. left. left. lia. }
replace (SPV + -64) with SP in * by lia.
destruct (Z.eqb_spec (zlen src) 0) as [Z0|Z0].
{ wk_if_true.
  assert (RSE : read_stats src = Err ZSTD_error_srcSize_wrong).
  { destruct src; [reflexivity|cbn in Z0; lia]. }
  eapply (rsA_exit m1 _ (-72)); [exact FRA2|exact STL|exact MIm|exact (mg_prs m1 MG1)|exact AH1|exact RSE|].
  cbn. unfold ZSTD_error_srcSize_wrong. split; [reflexivity|lia]. }
pose proof (AS ltac:(lia)) as AS'.
pose proof (ablk_lin _ _ AS') as (Sa & Sb & Sc & Sd).
unfold AIMG_HI in Sa.
wk_if_false.
zstep. wk_if_false.
zstep. unfold AHUF_RSTATS. zstep. zstep. zstep. zstep.
assert (USRC1 : unpoisoned m1 S (S + zlen src)) by (eapply bufA_unpoisoned; [exact AH1|apply bufA_of_bufH; exact (HSB0 ltac:(lia))|lia]).
destruct (AF_fse_rd_base.chkB m1 S (S + zlen src) S USRC1 ltac:(lia) ltac:(lia)) as (b & RDB & CK & SR).
destruct (HSB0 ltac:(lia)) as (pS & AS0 & NS0 & INS & XS1 & XS2).
assert (RSH : rng RNG (Z.shiftr S 3 + 2147450880) 1).
{ destruct (AI_block _ _ _ _ _ _ _ _ _ AH1 INS) as (_ & (_ & _ & _ & A16) & _ & RSAs & _).
  apply (rng_sub _ _ _ _ _ RSAs); unfold shad, shlen, ASHOFF; rewrite ?nshad_div, ?Z.shiftr_div_pow2 by lia; change (2^3) with 8; lia. }
step.
rewrite sxb_sval. clear RDB.
assert (J84 : forall t0' t1', evtF bsegs RNG POST
  (MS (mkR ra (Z_to_bv 64 SP) gp tp t0' t1' t2 (Z_to_bv 64 RK) s1 (Z_to_bv 64 (-72)) (Z_to_bv 64 256) (Z_to_bv 64 HW) (Z_to_bv 64 NSP)
           (Z_to_bv 64 TLP) (Z_to_bv 64 S) (Z_to_bv 64 (zlen src)) (Z_to_bv 64 W) s2 s3 (Z_to_bv 64 2147450880) s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
      FR (Z_to_bv 64 (AHUF_RSTATS + 84)) fc None m1 (seg_rom bsegs))).
{ intros t0' t1'.
pose proof (rsA_regions_mg m1 MG1) as (HW1 & RK1 & NS1 & TL1 & SR1 & WK1).
assert (CB : 0 <= Znth 0 src < 256).
{ destruct src as [|c0 r]; [cbn in Z0; lia|]. inversion BYS; subst. exact H1. }
pose proof (AI_block _ _ _ _ _ _ _ _ _ AH1 INS) as (_ & _ & RSA & _).
assert (RS : rng RNG S (zlen src)) by (apply (rng_sub _ _ _ _ _ RSA); lia).
unfold AHUF_RSTATS. wk_step.
rewrite (sxb_eqA _ CB).
assert (RP : rsA_pre m1) by (split; [exact AH1|split; [exact MG1|split; [exact FRA2|split; [exact STL|exact MIm]]]]).
destruct (Z.ltb_spec (Znth 0 src) 128) as [C7|C7].
- replace (Znth 0 src <? 128) with true by (symmetry; apply Z.ltb_lt; lia). cbv iota.
  zstep. zstep. rewrite (land255A _ CB). rewrite (lts_pos_byteA (Znth 0 src)) by lia. cbv iota.
  eapply (rsA_fse m1 (Znth 0 src)); [exact RP|reflexivity|lia|lia].
- replace (Znth 0 src <? 128) with false by (symmetry; apply Z.ltb_ge; lia). cbv iota.
  zstep. zstep. rewrite (land255_negA _ CB).
  lazymatch goal with |- context [bv_lts (Z_to_bv 64 (Znth 0 src + ?K)) _] =>
    replace K with (2^64 - 256) by reflexivity end.
  rewrite (lts_neg_byteA (Znth 0 src)) by lia. cbv iota.
  eapply (rsA_direct m1 (Znth 0 src)); [exact RP|reflexivity|lia|lia].
}
unfold AHUF_RSTATS in J84.
zstep.
destruct CK as [CK|CK].
- wk_if_false. apply J84.
- wk_if_true. zstep. zstep.
  assert (L7 : Z.land S 7 = S mod 8) by (change 7 with (Z.ones 3); rewrite Z.land_ones by lia; reflexivity).
  pose proof (Z.mod_pos_bound S 8 ltac:(lia)) as M8.
  assert (LT : bv_lts (Z_to_bv 64 (Z.land S 7)) (Z_to_bv 64 (sval b)) = true).
  { rewrite L7. unfold bv_lts. rewrite !bv_signed_small; rewrite ?inr64_unsigned_lit by (unfold inr64; lia); [apply Z.ltb_lt; lia|lia|lia]. }
  rewrite LT. cbv iota. apply J84.
Qed.
End RSA.

