intros AI rng_fs kk FDWK. unfold huf_rstats_stmtA.
intros L RNG ra gp tp t0 t1 t2 s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 FR fc m st LB SPV HW RK NSP TLP S W
  src jh jr jw nsv tlv lo rstk.
intros.
eapply rsA_main; eassumption.
Qed.
